import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.DYAmjhAm.js";const f=JSON.parse('{"title":"Interface: PropertyChangedEventArgs","description":"","frontmatter":{},"headers":[],"relativePath":"api/interfaces/PropertyChangedEventArgs.md","filePath":"api/interfaces/PropertyChangedEventArgs.md","lastUpdated":null}'),n={name:"api/interfaces/PropertyChangedEventArgs.md"};function p(c,e,i,s,h,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">breeze-client</a> / PropertyChangedEventArgs</p><h1 id="interface-propertychangedeventargs" tabindex="-1">Interface: PropertyChangedEventArgs <a class="header-anchor" href="#interface-propertychangedeventargs" aria-label="Permalink to &quot;Interface: PropertyChangedEventArgs&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/entity/entity-aspect.ts#L74" target="_blank" rel="noreferrer">src/entity/entity-aspect.ts:74</a></p><p>The argument to an entity&#39;s <a href="./../classes/EntityAspect#propertychanged">EntityAspect.propertyChanged</a> event. It is also the <code>args</code> of an <a href="./EntityChangedEventArgs">EntityChangedEventArgs</a> for <a href="./../classes/EntityAction#propertychange">EntityAction.PropertyChange</a>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="entity" tabindex="-1">entity <a class="header-anchor" href="#entity" aria-label="Permalink to &quot;entity&quot;">​</a></h3><blockquote><p><strong>entity</strong>: <a href="./Entity"><code>Entity</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/entity/entity-aspect.ts#L76" target="_blank" rel="noreferrer">src/entity/entity-aspect.ts:76</a></p><p>The entity that changed. For a property of a complex object, the entity that holds it.</p><hr><h3 id="newvalue" tabindex="-1">newValue? <a class="header-anchor" href="#newvalue" aria-label="Permalink to &quot;newValue?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>newValue?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/entity/entity-aspect.ts#L92" target="_blank" rel="noreferrer">src/entity/entity-aspect.ts:92</a></p><p>The value after the change, converted to the property&#39;s data type where Breeze can.</p><hr><h3 id="oldvalue" tabindex="-1">oldValue? <a class="header-anchor" href="#oldvalue" aria-label="Permalink to &quot;oldValue?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>oldValue?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/entity/entity-aspect.ts#L90" target="_blank" rel="noreferrer">src/entity/entity-aspect.ts:90</a></p><p>The value before the change.</p><hr><h3 id="parent" tabindex="-1">parent? <a class="header-anchor" href="#parent" aria-label="Permalink to &quot;parent?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>parent?</strong>: <a href="./../type-aliases/StructuralObject"><code>StructuralObject</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/entity/entity-aspect.ts#L85" target="_blank" rel="noreferrer">src/entity/entity-aspect.ts:85</a></p><p>The object whose property was set: the entity itself, or the complex object that owns the property.</p><hr><h3 id="property" tabindex="-1">property? <a class="header-anchor" href="#property" aria-label="Permalink to &quot;property?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>property?</strong>: <a href="./../type-aliases/EntityProperty"><code>EntityProperty</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/entity/entity-aspect.ts#L88" target="_blank" rel="noreferrer">src/entity/entity-aspect.ts:88</a></p><p>The <a href="./../classes/DataProperty">DataProperty</a> or <a href="./../classes/NavigationProperty">NavigationProperty</a> that changed. It belongs to the type of <code>parent</code>, which is not the entity&#39;s type when <code>parent</code> is a complex object.</p><hr><h3 id="propertyname" tabindex="-1">propertyName <a class="header-anchor" href="#propertyname" aria-label="Permalink to &quot;propertyName&quot;">​</a></h3><blockquote><p><strong>propertyName</strong>: <code>string</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/entity/entity-aspect.ts#L82" target="_blank" rel="noreferrer">src/entity/entity-aspect.ts:82</a></p><p>The name of the property that changed. For a property of a complex object it is a path from the entity, such as <code>&quot;location.city&quot;</code>, with no index for an element of a complex array.</p><p><code>null</code> when any number of properties may have changed at once - when a query or save merges values into the entity, or its changes are rejected. The other members are then not set.</p>',35)])])}const y=t(n,[["render",p]]);export{f as __pageData,y as default};
